dict.string:
.navbar {
	font-family: 'Hoefler Text', 'Times New Roman', serif;
	font-size: .9em;
	color: #817B67;
	margin: 0px;
	line-height: 25px;
}

.navbar-bg {
	text-align: left;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	display: inline;
	padding: 0 25px 0 0px;
}


li a {
	text-decoration: none;
	padding: 0px;
	color: #817B67;
}

li a:visited {
	text-decoration: none;
	padding: 0px;
	color: #817B67;
}

li a:hover{
 	color: #3F3F3C;
	text-decoration: none;}


li.current-page a{	 color: #3F3F3C;
	text-decoration: none;}
